const canonical = `${siteUrl}${path === "/" ? "" : path}`;
const baseSchemas = [
  {
    "@context": "https://schema.org",
    "@type": ["Organization", "LocalBusiness"],
    name: siteConfig.businessName,
    legalName: siteConfig.legalBusinessName,
    url: siteUrl,
    telephone: siteConfig.phone,
